}

pub fn collect_with_cancellation(parent: CancellationToken) -> Result<HardwareTelemetrySnapshot> {
    let mut warnings = Vec::new();
    let mut provider_faults = Vec::new();

    let storage = match run_isolated_gated_with_token(
        storage_gate(),
